insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060001', '$F(x)=x^2+C$.', 'Uma integral não é uma receita isolada: ela desfaz uma derivada ou acumula pequenas variações. O caminho seguro é identificar a estrutura da função, escolher a regra compatível e verificar o resultado derivando-o ou comparando a área acumulada. A constante de integração só aparece quando não há limites definidos.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
