insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000600501', '40000000-0000-4000-8000-000000060050', 'A', '$13$ m', 1), ('50000000-0000-4000-8000-000000600502', '40000000-0000-4000-8000-000000060050', 'B', '$15$ m', 2), ('50000000-0000-4000-8000-000000600503', '40000000-0000-4000-8000-000000060050', 'C', '$10$ m', 3), ('50000000-0000-4000-8000-000000600504', '40000000-0000-4000-8000-000000060050', 'D', '$26$ m', 4)
