insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600501', '40000000-0000-4000-8000-000000060050', 'Se os lados são x e y, então 2x mais 2y é o perímetro.', 1), ('60000000-0000-4000-8000-000000600502', '40000000-0000-4000-8000-000000060050', 'A área máxima, com perímetro fixo, ocorre quando o retângulo é um quadrado.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060050', '$x=y=13$ m.', 'A otimização começa transformando a restrição geométrica em uma função de uma variável. Com o perímetro fixo, cada aumento em um lado reduz o outro; a área se torna uma parábola côncava. Seu vértice representa a maior área possível e, neste caso, produz lados iguais.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600501', '40000000-0000-4000-8000-000000060050', 'Use o perímetro', '$2x+2y=52 \Rightarrow y=26-x.$', 1), ('70000000-0000-4000-8000-000000600502', '40000000-0000-4000-8000-000000060050', 'Escreva a área', '$A(x)=x(26-x).$', 2), ('70000000-0000-4000-8000-000000600503', '40000000-0000-4000-8000-000000060050', 'Localize o vértice', '$A^{\prime}(x)=26-2x=0 \Rightarrow x=13, y=13.$', 3)
